package com.xdownload.mobile;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
/** Password-encrypted, whitelisted settings only; no browser history, URLs or vault keys. */
public final class SettingsBackupActivity extends SecureActivity{
 static final String[] BOOL={"english","light","wifi","battery","http","js","block_trackers","data_saver","media_enabled","torrent_enabled","amoled","dynamic_ranges","one_click"};
 static final String[] INT={"mode","rate_kib","global_http_kib","parallel_jobs","connections","search_engine","player_repeat","player_speed","eq_preset","bass_strength","accent","font_scale"};
 static final int[] MIN={0,0,0,1,1,0,0,50,-1,0,0,85},MAX={4,102400,102400,3,32,2,2,200,31,1000,5,125},DEF={1,0,0,2,8,0,0,100,-1,0,0,100};
 static final int MAX_JSON=16384;
 final ExecutorService io=Executors.newSingleThreadExecutor();EditText password;Button export,restore;TextView status;boolean en,busy;volatile boolean dead;char[] pending;
 String tr(String ar,String eng){return en?eng:ar;}
 static JSONObject snapshot(SharedPreferences p)throws JSONException{JSONObject j=new JSONObject().put("schema",1);for(String k:BOOL)if(p.contains(k))j.put(k,p.getBoolean(k,false));for(int i=0;i<INT.length;i++)j.put(INT[i],p.getInt(INT[i],DEF[i]));return j;}
 static void apply(SharedPreferences p,JSONObject j)throws JSONException,IOException{if(j.optInt("schema",-1)!=1)throw new IOException("Unknown encrypted settings schema");SharedPreferences.Editor ed=p.edit();for(String k:BOOL)if(j.opt(k) instanceof Boolean)ed.putBoolean(k,j.getBoolean(k));for(int i=0;i<INT.length;i++)MainActivity.restoreInt(j,ed,INT[i],MIN[i],MAX[i]);if(!ed.commit())throw new IOException("Cannot write settings");}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);en=Store.settings(this).getBoolean("english",false);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);TextView head=new TextView(this);head.setText(tr("نسخة إعدادات مشفرة","Encrypted settings backup"));head.setTextSize(22);l.addView(head);TextView hint=new TextView(this);hint.setText(tr("AES-256-GCM. الإعدادات فقط، دون ملفاتك أو كلمات المرور أو سجل المتصفح. لا يمكن استعادة كلمة مرور النسخة.","AES-256-GCM. Settings only; no files, credentials or browsing history. Backup password cannot be recovered."));l.addView(hint);password=new EditText(this);password.setInputType(129);password.setHint(tr("كلمة مرور 8 أحرف على الأقل","Password, at least 8 characters"));l.addView(password);export=new Button(this);export.setText(tr("تصدير مشفر","Encrypted export"));export.setOnClickListener(v->pick(true));l.addView(export);restore=new Button(this);restore.setText(tr("استعادة مشفرة","Encrypted restore"));restore.setOnClickListener(v->pick(false));l.addView(restore);status=new TextView(this);l.addView(status);setContentView(l);}
 void state(boolean b){busy=b;password.setEnabled(!b);export.setEnabled(!b);restore.setEnabled(!b);}
 void wipe(){if(pending!=null){Arrays.fill(pending,'\0');pending=null;}}
 void pick(boolean writing){if(busy)return;wipe();pending=password.getText().toString().toCharArray();password.setText("");if(pending.length<8){wipe();status.setText(tr("كلمة المرور قصيرة","Password too short"));return;}state(true);try{Intent i=new Intent(writing?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(writing?"application/octet-stream":"*/*");if(writing)i.putExtra(Intent.EXTRA_TITLE,"XDownload-settings.xdvault");startActivityForResult(i,writing?1:2);}catch(RuntimeException e){wipe();state(false);status.setText(tr("منتقي الملفات غير متاح","Document picker unavailable"));}}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r!=1&&r!=2)return;if(result!=RESULT_OK||data==null||data.getData()==null||pending==null){wipe();state(false);return;}char[] pass=pending;pending=null;Uri uri=data.getData();io.execute(()->{File clear=null,encrypted=null;try{clear=File.createTempFile("studio-in-",".json",getCacheDir());encrypted=File.createTempFile("studio-out-",".xdvault",getCacheDir());if(r==1){byte[] bytes=snapshot(Store.settings(this)).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(OutputStream out=new FileOutputStream(clear)){out.write(bytes);}FileTools.crypt(clear,encrypted,pass,true);try(InputStream in=new FileInputStream(encrypted);OutputStream out=getContentResolver().openOutputStream(uri,"w")){AudioStudioActivity.copy(in,out);}}else{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(encrypted)){if(in==null)throw new IOException("Cannot read backup");byte[] buf=new byte[4096];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>MAX_JSON+FileTools.VAULT_OVERHEAD)throw new IOException("Settings backup too large");out.write(buf,0,n);}}FileTools.crypt(encrypted,clear,pass,false);if(clear.length()>MAX_JSON)throw new IOException("Settings backup too large");JSONObject j=new JSONObject(new String(java.nio.file.Files.readAllBytes(clear.toPath()),java.nio.charset.StandardCharsets.UTF_8));apply(Store.settings(this),j);}report(r==1?tr("تم التصدير","Export complete"):tr("تمت الاستعادة. أعد فتح التطبيق لتطبيق المظهر والمتصفح.","Restored. Reopen app to refresh appearance and browser."));}catch(Exception ex){report(tr("فشلت العملية؛ تحقق من الملف وكلمة المرور","Operation failed; check file and password"));}finally{Arrays.fill(pass,'\0');if(clear!=null)clear.delete();if(encrypted!=null)encrypted.delete();}});}
 void report(String msg){runOnUiThread(()->{if(!dead){status.setText(msg);state(false);}});}
 @Override protected void onDestroy(){dead=true;wipe();io.shutdownNow();super.onDestroy();}
}
